def search_substr(fullText, searchText, allowOverlap=True):
    if not searchText:
        return 0

    count = 0
    start = 0

    while start <= len(fullText) - len(searchText):
        index = fullText.find(searchText, start)
        if index == -1:
            break
        count += 1
        if allowOverlap:
            start = index + 1
        else:
            start = index + len(searchText)

    return count
